mapper.select:
SELECT count(*) totcnt FROM ttok.member member, ttok.branch branch WHERE member.branchid = branch.branchid
AND member.branchid = #{session_branchid}
AND member.membername LIKE #{likeQuery}

SELECT R1.* FROM( SELECT branch.branchid, branch.branchname, member.memberno, member.memberid, member.type, member.membername, member.schoolcode, member.schoolname, member.grade, member.gender, member.contact, member.email, member.os, member.pushtoken, member.marketing, member.push, DATE_FORMAT(member.regdate, '%Y-%m-%d %H:%i:%s') regdate FROM ttok.member member, ttok.branch branch
AND member.branchid = branch.branchid
AND member.branchid = #{session_branchid}
AND member.membername LIKE #{likeQuery}
member.memberid member.membername member.type member.schoolcode member.schoolname member.grade member.contact member.email member.os member.marketing member.push member.regdate ASC ASC DESC
) R1
LIMIT ${length} OFFSET ${start}

mapper.delete:
DELETE FROM ttok.member

  AND branchid = #{branchid}
  AND memberid = #{memberid}
